def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 700:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive:
        return float(min(budget, 8.0))

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0
    max_prev = max(prev_bids) if prev_bids else 0.0
    min_prev = min(prev_bids) if prev_bids else 0.0

    supply_ratio = float(supply) / float(WATER_REQ)
    contested = supply_ratio < 1.45
    abundant = supply_ratio >= 1.75

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 2

    if abundant and urgency == 0:
        bid = 10.0
    elif abundant:
        bid = 22.0 + 8.0 * urgency
    elif contested:
        bid = 34.0 + 10.0 * urgency
    else:
        bid = 22.0 + 9.0 * urgency

    if prev_bids:
        if max_prev >= 140:
            if urgency >= 4:
                bid = max(bid, min(0.92 * DAILY_SALARY, max_prev * 0.72))
            elif urgency >= 2:
                bid = max(bid, 48.0)
            else:
                bid = min(bid, 18.0)
        elif max_prev >= 100:
            if urgency >= 3:
                bid = max(bid, min(0.88 * DAILY_SALARY, avg_prev * 0.58))
            elif contested:
                bid = max(bid, 30.0)
            else:
                bid = min(bid, 16.0)
        else:
            target = avg_prev + 2.5
            if urgency >= 2:
                bid = max(bid, target)
            else:
                bid = max(bid, min(28.0, target))

    if desperate_count >= 2 and contested:
        bid += 8.0
    elif desperate_count == 0 and abundant:
        bid -= 4.0

    if rich_count >= 2 and urgency <= 1:
        bid -= 3.0

    if day >= 8:
        if hp >= 6 and budget < 160:
            bid = min(bid, 20.0)
        elif urgency >= 3:
            bid += 6.0

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = max(0.0, budget - DAILY_SALARY * (10 - day) * 0.55)
        bid = min(bid, max(18.0, reserve_floor + 20.0))

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, 62.0)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(bid, 46.0)

    bid = max(0.0, bid)
    bid = min(float(budget), float(bid))
    return float(round(bid, 2))

